#include <bits/stdc++.h>
using namespace std;
struct A{int w,d,z; bool operator==(const A&o)const{return w==o.w&&d==o.d&&z==o.z;}};
A T[1200][2];bool present[1200];vector<int>states;
int main(int argc,char**argv){ifstream in(argv[1]);string line;while(getline(in,line)){if(line.empty()||line[0]=='#')continue;istringstream s(line);int q,b,w,z;char d;s>>q>>b>>w>>d>>z;T[q][b]={w,d=='R'?1:-1,z};present[q]=true;}for(int q=0;q<1200;q++)if(present[q])states.push_back(q);int K=argc>2?atoi(argv[2]):7,C=K,W=2*K+1;mt19937 rng(10723);vector<uint64_t>samples={0,(1ull<<W)-1,0x5555555&((1ull<<W)-1),0xAAAAAAA&((1ull<<W)-1)};for(int j=0;j<40;j++)samples.push_back(rng()&((1ull<<W)-1));long long tried=0,filtered=0,passed=0;
for(int a:states)for(int b=0;b<2;b++){A old=T[a][b];for(int w=0;w<2;w++)for(int d:{-1,1})for(int z:states){A alt{w,d,z};if(alt==old)continue;tried++;int maxstep=0;set<pair<int,int>>deps;auto check=[&](uint64_t bits,bool record){bits=(bits&~(1ull<<C))|((uint64_t)b<<C);uint64_t expected=(bits&~(1ull<<C))|((uint64_t)old.w<<C);int q=a,h=C;uint64_t tape=bits;for(int n=1;n<=K;n++){if(h<0||h>=W||!present[q])return false;int x=(tape>>h)&1;A act=(q==a&&x==b)?alt:T[q][x];if(record&&!(q==a&&x==b))deps.insert({q,x});tape=(tape&~(1ull<<h))|((uint64_t)act.w<<h);h+=act.d;q=act.z;if(q==old.z&&h==C+old.d&&tape==expected){maxstep=max(maxstep,n);return true;}}return false;};bool ok=true;for(auto bits:samples){if(!check(bits,false)){ok=false;break;}}if(!ok)continue;filtered++;for(uint64_t bits=0;bits<(1ull<<W);bits++){if(((bits>>C)&1)!=(unsigned)b)continue;if(!check(bits,true)){ok=false;break;}}if(ok){passed++;cout<<a<<' '<<b<<' '<<w<<' '<<d<<' '<<z<<' '<<maxstep<<' ';for(auto p:deps)cout<<p.first<<':'<<p.second<<',';cout<<'\n';}}
}cerr<<"tried "<<tried<<" filtered "<<filtered<<" passed "<<passed<<"\n";}
